package dev.pxxl;import io.vertx.core.*;import io.vertx.ext.web.Router;public class Application{public static void main(String[]args){Vertx v=Vertx.vertx();Router r=Router.router(v);r.get("/").handler(c->c.json(new JsonObject().put("service","Pxxl Vertx API")));r.get("/health").handler(c->c.json(new JsonObject().put("status","ok")));r.get("/api").handler(c->c.json(new JsonObject().put("message","Hello from Vertx")));int p=Integer.parseInt(System.getenv().getOrDefault("PORT","8080"));v.createHttpServer().requestHandler(r).listen(p,"0.0.0.0");}}
